import{_ as l,a0 as o,w as d,s as h,ao as p,I as t,x as a,a1 as i,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"学习用 Python 编程时要避免的 3 个错误 | LCTT x X-CMD","titleTemplate":false,"description":"学习用 Python 编程时要避免的 3 个错误 | LCTT (201708) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"学习用 Python 编程时要避免的 3 个错误 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"学习用 Python 编程时要避免的 3 个错误 | LCTT (201708) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201708/20170623 3 mistakes to avoid when learning to code in Python","title":"学习用 Python 编程时要避免的 3 个错误","tag":"201708","desc":""},"relativePath":"201708/20170623 3 mistakes to avoid when learning to code in Python.md","filePath":"[post].md"}'),r={name:"201708/20170623 3 mistakes to avoid when learning to code in Python.md"};function g(c,s,k,b,u,f){const n=o("Link");return d(),h("div",null,[s[23]||(s[23]=p(`<h1 id="学习用-python-编程时要避免的-3-个错误" tabindex="-1">学习用 Python 编程时要避免的 3 个错误 <a class="header-anchor" href="#学习用-python-编程时要避免的-3-个错误" aria-label="Permalink to “学习用 Python 编程时要避免的 3 个错误”">​</a></h1><blockquote><p>这些错误会造成很麻烦的问题，需要数小时才能解决。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/images/life/blocks_building.png?itok=q0_Wo8Tr" alt="学习用 python 编码时要避免的 3 个错误" title="3 mistakes to avoid when learning to code in Python"></p><p>当你做错事时，承认错误并不是一件容易的事，但是犯错是任何学习过程中的一部分，无论是学习走路，还是学习一种新的编程语言都是这样，比如学习 Python。</p><p>为了让初学 Python 的程序员避免犯同样的错误，以下列出了我学习 Python 时犯的三种错误。这些错误要么是我长期以来经常犯的，要么是造成了需要几个小时解决的麻烦。</p><p>年轻的程序员们可要注意了，这些错误是会浪费一下午的！</p><h3 id="_1、-可变数据类型作为函数定义中的默认参数" tabindex="-1">1、 可变数据类型作为函数定义中的默认参数 <a class="header-anchor" href="#_1、-可变数据类型作为函数定义中的默认参数" aria-label="Permalink to “1、 可变数据类型作为函数定义中的默认参数”">​</a></h3><p>这似乎是对的？你写了一个小函数，比如，搜索当前页面上的链接，并可选将其附加到另一个提供的列表中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>def search_for_links(page, add_to=[]):</span></span>
<span class="line"><span>    new_links = page.search_for_links()</span></span>
<span class="line"><span>    add_to.extend(new_links)</span></span>
<span class="line"><span>    return add_to</span></span></code></pre></div><p>从表面看，这像是十分正常的 Python 代码，事实上它也是，而且是可以运行的。但是，这里有个问题。如果我们给 <code>add_to</code> 参数提供了一个列表，它将按照我们预期的那样工作。但是，如果我们让它使用默认值，就会出现一些神奇的事情。</p><p>试试下面的代码：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>def fn(var1, var2=[]):</span></span>
<span class="line"><span>    var2.append(var1)</span></span>
<span class="line"><span>    print var2</span></span>
<span class="line"><span></span></span>
<span class="line"><span>fn(3)</span></span>
<span class="line"><span>fn(4)</span></span>
<span class="line"><span>fn(5)</span></span></code></pre></div><p>可能你认为我们将看到：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[3]</span></span>
<span class="line"><span>[4]</span></span>
<span class="line"><span>[5]</span></span></code></pre></div><p>但实际上，我们看到的却是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[3]</span></span>
<span class="line"><span>[3, 4]</span></span>
<span class="line"><span>[3, 4, 5]</span></span></code></pre></div><p>为什么呢？如你所见，每次都使用的是同一个列表，输出为什么会是这样？在 Python 中，当我们编写这样的函数时，这个列表被实例化为函数定义的一部分。当函数运行时，它并不是每次都被实例化。这意味着，这个函数会一直使用完全一样的列表对象，除非我们提供一个新的对象：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fn(3, [4])</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[4, 3]</span></span></code></pre></div><p>答案正如我们所想的那样。要想得到这种结果，正确的方法是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>def fn(var1, var2=None):</span></span>
<span class="line"><span>    if not var2:</span></span>
<span class="line"><span>        var2 = []</span></span>
<span class="line"><span>    var2.append(var1)</span></span></code></pre></div><p>或是在第一个例子中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>def search_for_links(page, add_to=None):</span></span>
<span class="line"><span>    if not add_to:</span></span>
<span class="line"><span>        add_to = []</span></span>
<span class="line"><span>    new_links = page.search_for_links()</span></span>
<span class="line"><span>    add_to.extend(new_links)</span></span>
<span class="line"><span>    return add_to</span></span></code></pre></div>`,23)),t("p",null,[s[3]||(s[3]=a("这将在模块加载的时候移走实例化的内容，以便每次运行函数时都会发生列表实例化。请注意，对于不可变数据类型，比如",-1)),i(n,{href:"https://docs.python.org/2/library/functions.html?highlight=tuple#tuple"},{default:e(()=>[...s[0]||(s[0]=[t("strong",null,"元组",-1)])]),_:1}),s[4]||(s[4]=a("、",-1)),i(n,{href:"https://docs.python.org/2/library/string.html"},{default:e(()=>[...s[1]||(s[1]=[t("strong",null,"字符串",-1)])]),_:1}),s[5]||(s[5]=a("、",-1)),i(n,{href:"https://docs.python.org/2/library/functions.html#int"},{default:e(()=>[...s[2]||(s[2]=[t("strong",null,"整型",-1)])]),_:1}),s[6]||(s[6]=a("，是不需要考虑这种情况的。这意味着，像下面这样的代码是非常可行的：",-1))]),s[24]||(s[24]=p(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>def func(message=&quot;my message&quot;):</span></span>
<span class="line"><span>    print message</span></span></code></pre></div><h3 id="_2、-可变数据类型作为类变量" tabindex="-1">2、 可变数据类型作为类变量 <a class="header-anchor" href="#_2、-可变数据类型作为类变量" aria-label="Permalink to “2、 可变数据类型作为类变量”">​</a></h3><p>这和上面提到的最后一个错误很相像。思考以下代码：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>class URLCatcher(object):</span></span>
<span class="line"><span>    urls = []</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    def add_url(self, url):</span></span>
<span class="line"><span>        self.urls.append(url)</span></span></code></pre></div><p>这段代码看起来非常正常。我们有一个储存 URL 的对象。当我们调用 add_url 方法时，它会添加一个给定的 URL 到存储中。看起来非常正确吧？让我们看看实际是怎样的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>a = URLCatcher()</span></span>
<span class="line"><span>a.add_url(&#39;http://www.google.com&#39;)</span></span>
<span class="line"><span>b = URLCatcher()</span></span>
<span class="line"><span>b.add_url(&#39;http://www.bbc.co.hk&#39;)</span></span></code></pre></div><p>b.urls：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[&#39;http://www.google.com&#39;, &#39;http://www.bbc.co.uk&#39;]</span></span></code></pre></div><p>a.urls：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[&#39;http://www.google.com&#39;, &#39;http://www.bbc.co.uk&#39;]</span></span></code></pre></div><p>等等，怎么回事？！我们想的不是这样啊。我们实例化了两个单独的对象 <code>a</code> 和 <code>b</code>。把一个 URL 给了 <code>a</code>，另一个给了 <code>b</code>。这两个对象怎么会都有这两个 URL 呢？</p><p>这和第一个错例是同样的问题。创建类定义时，URL 列表将被实例化。该类所有的实例使用相同的列表。在有些时候这种情况是有用的，但大多数时候你并不想这样做。你希望每个对象有一个单独的储存。为此，我们修改代码为：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>class URLCatcher(object):</span></span>
<span class="line"><span>    def __init__(self):</span></span>
<span class="line"><span>        self.urls = []</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    def add_url(self, url):</span></span>
<span class="line"><span>        self.urls.append(url)</span></span></code></pre></div><p>现在，当创建对象时，URL 列表被实例化。当我们实例化两个单独的对象时，它们将分别使用两个单独的列表。</p><h3 id="_3、-可变的分配错误" tabindex="-1">3、 可变的分配错误 <a class="header-anchor" href="#_3、-可变的分配错误" aria-label="Permalink to “3、 可变的分配错误”">​</a></h3>`,15)),t("p",null,[s[8]||(s[8]=a("这个问题困扰了我一段时间。让我们做出一些改变，并使用另一种可变数据类型 - ",-1)),i(n,{href:"https://docs.python.org/2/library/stdtypes.html?highlight=dict#dict"},{default:e(()=>[...s[7]||(s[7]=[t("strong",null,"字典",-1)])]),_:1}),s[9]||(s[9]=a("。",-1))]),s[25]||(s[25]=p(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>a = {&#39;1&#39;: &quot;one&quot;, &#39;2&#39;: &#39;two&#39;}</span></span></code></pre></div><p>现在，假设我们想把这个字典用在别的地方，且保持它的初始数据完整。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>b = a</span></span>
<span class="line"><span></span></span>
<span class="line"><span>b[&#39;3&#39;] = &#39;three&#39;</span></span></code></pre></div><p>简单吧？</p><p>现在，让我们看看原来那个我们不想改变的字典 <code>a</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{&#39;1&#39;: &quot;one&quot;, &#39;2&#39;: &#39;two&#39;, &#39;3&#39;: &#39;three&#39;}</span></span></code></pre></div><p>哇等一下，我们再看看 <strong>b</strong>？</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{&#39;1&#39;: &quot;one&quot;, &#39;2&#39;: &#39;two&#39;, &#39;3&#39;: &#39;three&#39;}</span></span></code></pre></div><p>等等，什么？有点乱……让我们回想一下，看看其它不可变类型在这种情况下会发生什么，例如一个<strong>元组</strong>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>c = (2, 3)</span></span>
<span class="line"><span>d = c</span></span>
<span class="line"><span>d = (4, 5)</span></span></code></pre></div><p>现在 <code>c</code> 是 <code>(2, 3)</code>，而 <code>d</code> 是 <code>(4, 5)</code>。</p><p>这个函数结果如我们所料。那么，在之前的例子中到底发生了什么？当使用可变类型时，其行为有点像 <strong>C</strong> 语言的一个指针。在上面的代码中，我们令 <code>b = a</code>，我们真正表达的意思是：<code>b</code> 成为 <code>a</code> 的一个引用。它们都指向 Python 内存中的同一个对象。听起来有些熟悉？那是因为这个问题与先前的相似。其实，这篇文章应该被称为「可变引发的麻烦」。</p><p>列表也会发生同样的事吗？是的。那么我们如何解决呢？这必须非常小心。如果我们真的需要复制一个列表进行处理，我们可以这样做：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>b = a[:]</span></span></code></pre></div><p>这将遍历并复制列表中的每个对象的引用，并且把它放在一个新的列表中。但是要注意：如果列表中的每个对象都是可变的，我们将再次获得它们的引用，而不是完整的副本。</p><p>假设在一张纸上列清单。在原来的例子中相当于，A 某和 B 某正在看着同一张纸。如果有个人修改了这个清单，两个人都将看到相同的变化。当我们复制引用时，每个人现在有了他们自己的清单。但是，我们假设这个清单包括寻找食物的地方。如果“冰箱”是列表中的第一个，即使它被复制，两个列表中的条目也都指向同一个冰箱。所以，如果冰箱被 A 修改，吃掉了里面的大蛋糕，B 也将看到这个蛋糕的消失。这里没有简单的方法解决它。只要你记住它，并编写代码的时候，使用不会造成这个问题的方式。</p><p>字典以相同的方式工作，并且你可以通过以下方式创建一个昂贵副本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>b = a.copy()</span></span></code></pre></div><p>再次说明，这只会创建一个新的字典，指向原来存在的相同的条目。因此，如果我们有两个相同的列表，并且我们修改字典 <code>a</code> 的一个键指向的可变对象，那么在字典 b 中也将看到这些变化。</p><p>可变数据类型的麻烦也是它们强大的地方。以上都不是实际中的问题；它们是一些要注意防止出现的问题。在第三个项目中使用昂贵复制操作作为解决方案在 99% 的时候是没有必要的。你的程序或许应该被改改，所以在第一个例子中，这些副本甚至是不需要的。</p><p><em>编程快乐！在评论中可以随时提问。</em></p><p>（题图： opensource.com）</p><hr><p>作者简介：</p><p>Pete Savage - Peter 是一位充满激情的开源爱好者，在过去十年里一直在推广和使用开源产品。他从 Ubuntu 社区开始，在许多不同的领域自愿参与音频制作领域的研究工作。在职业经历方面，他起初作为公司的系统管理员，大部分时间在管理和建立数据中心，之后在 Red Hat 担任 CloudForms 产品的主要测试工程师。</p><hr>`,26)),t("p",null,[s[11]||(s[11]=a("via: ",-1)),i(n,{href:"https://opensource.com/article/17/6/3-things-i-did-wrong-learning-python"},{default:e(()=>[...s[10]||(s[10]=[a("https://opensource.com/article/17/6/3-things-i-did-wrong-learning-python",-1)])]),_:1})]),t("p",null,[s[15]||(s[15]=a("作者：",-1)),i(n,{href:"https://opensource.com/users/psav"},{default:e(()=>[...s[12]||(s[12]=[a("Pete Savage",-1)])]),_:1}),s[16]||(s[16]=a(" 译者：",-1)),i(n,{href:"https://github.com/polebug"},{default:e(()=>[...s[13]||(s[13]=[a("polebug",-1)])]),_:1}),s[17]||(s[17]=a(" 校对：",-1)),i(n,{href:"https://github.com/wxy"},{default:e(()=>[...s[14]||(s[14]=[a("wxy",-1)])]),_:1})]),t("p",null,[s[20]||(s[20]=a("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[18]||(s[18]=[a("LCTT",-1)])]),_:1}),s[21]||(s[21]=a(" 原创编译，",-1)),i(n,{href:"https://linux.cn/"},{default:e(()=>[...s[19]||(s[19]=[a("Linux中国",-1)])]),_:1}),s[22]||(s[22]=a(" 荣誉推出",-1))])])}const v=l(r,[["render",g]]);export{C as __pageData,v as default};
